const data = $input.first().json;
const contact = (data.payload || [])[0];
return [{ json: { contact_id: contact ? contact.id : null } }];

const data = $input.first().json;
const conversations = data.payload || [];
const aberta = conversations.find(function (c) { return c.status === "open"; });
return [{ json: { conversation_id: aberta ? aberta.id : null } }];

